ai_strategy_agricultural_expansion = {
	icon = "gfx/interface/icons/ai_strategy_icons/agricultural_expansion.dds"

	type = administrative

	building_group_weights = {
		bg_agriculture = 2.0
		bg_ranching = 2.0
		bg_fishing = 1.5
		bg_plantations = 1.5
		bg_manufacturing = 0.5
	}

	goods_stances = {
		grain = { stance = wants_export }
		meat = { stance = wants_export }
		fish = { stance = wants_export }
		fruit = { stance = wants_export }
		liquor = { stance = wants_export }
		wine = { stance = wants_export }
		fabric = { stance = wants_export }
		fertilizer = {
			stance = wants_high_supply
			trigger = {
				has_technology_researched = intensive_agriculture
			}
		}
		tools = {
			stance = wants_high_supply
			trigger = {
				has_technology_researched = intensive_agriculture
			}
		}
	}

	possible = {
		always = yes
	}

	weight = {
		value = 10

		if = {
			limit = {
				OR = {
					is_in_geographic_region = geographic_region_europe
					is_in_geographic_region = geographic_region_north_america
					is_in_geographic_region = geographic_region_east_asia
					is_in_geographic_region = geographic_region_middle_east
					is_in_geographic_region = geographic_region_central_asia_old
					capital.region = sr:region_oceania
				}
			}
			add = 20
		}

		if = {
			limit = {
				exists = c:FRA
				c:FRA = this
				OR = {
					ruler = {
						has_variable = legitimist_leader
					}
					divided_monarchists_ai_legitimist = yes
				}
			}
			add = 20
		}

		if = {
			limit = {
				is_princely_state = yes
			}
			add = 10
		}

		if = {
			limit = { literacy_rate < 0.25 }
			multiply = 1.5
		}

		if = {
			limit = { literacy_rate < 0.35 }
			multiply = 1.5
		}

		if = {
			limit = { literacy_rate >= 0.50 }
			multiply = 0.5
		}

		if = {
			limit = {
				exists = ig:ig_landowners
				ig:ig_landowners ?= { is_powerful = yes }
			}
			multiply = 1.5
		}

		if = {
			limit = {
				exists = overlord
				overlord = {
					OR = {
						AND = {
							is_ai = no
							NOT = { has_law_or_variant = law_type:law_traditionalism }
						}
						has_strategy = ai_strategy_resource_expansion
						has_strategy = ai_strategy_industrial_expansion
					}
				}
			}
			multiply = 0.5
		}
	}
}

