ai_strategy_subject_strengthen_self = {
	icon = "gfx/interface/icons/ai_strategy_icons/subject_strengthen_self.dds"

	type = diplomatic

	undesirable_infamy_level = {
		value = 50
	}

	unacceptable_infamy_level = {
		value = 75
	}

	obligation_value = {
		# Rebellious AI wants to use obligations to break free
		if = {
			limit = {
				this.overlord ?= scope:target_country
			}
			add = 50
		}
		else = {
			add = 20
		}
	}

	diplomatic_play_boldness = {
		value = 25
	}

	recklessness = {
		value = 0.25
	}

	aggression = {
		value = 1

		# Not very likely to directly attack overlord
		if = {
			limit = {
				is_subject_of = scope:target_country
			}
			add = -0.75
		}

		# Opportunistic colonization is self-strengthening, right?
		if = {
			limit = {
				NOT = { is_country_type = unrecognized }
				scope:target_country = { is_country_type = unrecognized }
			}
			add = 1
		}
	}

	building_group_weights = {
		bg_army = 1.5
		bg_military_industry = 1.5
	}

	wargoal_weights = {
		independence = 0.0
		increase_autonomy = 5.0
		conquer_state = 1.5
		return_state = 1.5
	}

	secret_goal_scores = {
		defy = {
			trigger = {
				is_subject_of = scope:target_country
			}
			score = {
				value = 10000
			}
		}
		antagonize = {
			trigger = {
				is_subject_of = scope:target_country
			}
			score = {
				value = -10000
			}
		}
		none = {
			trigger = {
				is_subject_of = scope:target_country
			}
			score = {
				value = -10000
			}
		}
		comply = {
			trigger = {
				is_subject_of = scope:target_country
			}
			score = {
				value = -10000
			}
		}
		befriend = {
			trigger = {
				is_subject_of = scope:target_country
			}
			score = {
				value = -10000
			}
		}
		conquer = {
			trigger = {
				has_strategic_adjacency = scope:target_country
				scope:target_country.country_rank <= root.country_rank
				can_reach_target_country_to_conquer = { TARGET_COUNTRY = scope:target_country }
			}
			score = {
				if = {
					limit = {
						NOT = { is_country_type = unrecognized }
						scope:target_country = { NOT = { is_country_type = unrecognized } }
					}
					add = 25
				}
				else_if = {
					limit = {
						scope:target_country = { is_country_type = unrecognized }
					}
					add = 50
				}
			}
		}
	}

	become_subject_value = {
		value = -50
	}

	diplomatic_play_support = {
		value = 0

		if = { # More opportunistic
			limit = {
				scope:enemy_country = { root.overlord ?= this }
			}
			add = {
				value = 20
				desc = "AI_STRATEGY_SUPPORT_STRENGTHEN_SELF_OVERLORD_DISTRACTED"
			}
		}
	}

	treaty_category_scores = {
		military_defense = {
			value = 4
		}

		economy = {
			value = 3
		}
	}

	possible = {
		is_subject = yes
		liberty_desire >= 25
	}

	weight = {
		value = liberty_desire

		# AI implications for Power Blocs: 'Increased Self-Reliance' strategy is more likely for Blocs with Militarized Industry
		if = {
			limit = {
				liberty_desire >= 50
				power_bloc ?= {
					has_principle_group = principle_group:principle_group_military_industry
				}
			}
			multiply = 1.5
		}

		# Subjects that would collapse if independent should be more loyal
		if = {
			limit = {
				OR = {
					c:DEI ?= this
					has_government_type = gov_chartered_company
				}
			}
			multiply = 0.25
		}
	}
}

